package com.mamtrex.hospital.facility;
import com.mamtrex.hospital.audit.AuditService; import com.mamtrex.hospital.shared.NotFoundException; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/facility-work-orders") public class WorkOrderController { private final WorkOrderRepository repo; private final AuditService audit; public WorkOrderController(WorkOrderRepository r,AuditService a){repo=r;audit=a;} public record Request(@jakarta.validation.constraints.NotBlank String area, @jakarta.validation.constraints.NotBlank String category, @jakarta.validation.constraints.NotBlank String description, @jakarta.validation.constraints.NotBlank String priority, @jakarta.validation.constraints.NotBlank String status){} @PostMapping public WorkOrder create(@Valid @RequestBody Request r){var e=repo.save(new WorkOrder(r.area(), r.category(), r.description(), r.priority(), r.status()));audit.record("CREATE","WorkOrder",e.getId().toString(),"created");return e;} @GetMapping public List<WorkOrder> list(){return repo.findAll();} @GetMapping("/{id}") public WorkOrder get(@PathVariable UUID id){return repo.findById(id).orElseThrow(()->new NotFoundException("WorkOrder not found: "+id));} @DeleteMapping("/{id}") public void delete(@PathVariable UUID id){if(!repo.existsById(id))throw new NotFoundException("WorkOrder not found: "+id);repo.deleteById(id);audit.record("DELETE","WorkOrder",id.toString(),"deleted");} }
